using System.Windows; using System.Windows.Controls; using MizanDesktop.Models; using MizanDesktop.Services;
namespace MizanDesktop.Views; public partial class ExchangeRatesView:UserControl{readonly AppRepository repo;public ExchangeRatesView(AppRepository r){InitializeComponent();repo=r;Load();}void Load()=>Grid.ItemsSource=repo.GetExchangeRates();void Save_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(Currency.Text)||!decimal.TryParse(Rate.Text,out var rate)){MessageBox.Show("أدخل العملة وسعر صرف صحيح.");return;}try{repo.SaveExchangeRate(new ExchangeRate{Currency=Currency.Text.Trim().ToUpperInvariant(),Rate=rate});Load();Currency.Clear();Rate.Clear();}catch(Exception ex){MessageBox.Show(ex.Message,"خطأ");}}}
